  private *nearestControls(features: number[]): IterableIterator<ArcControlExample> {
    const size = this.controls.length;
    if (this.nearest.length < size) {
      const capacity = Math.max(size, this.nearest.length * 2);
      this.nearest = new Uint32Array(capacity);
      this.distances = new Float64Array(capacity);
    }
    const {nearest, distances} = this;
    let finite = true;
    for (let i = 0; i < size; i++) {
      nearest[i] = i;
      distances[i] = distance(this.controls[i].features, features);
      finite &&= Number.isFinite(distances[i]);
    }
    // A nonfinite comparator is not a total order. Preserve Array.sort's
    // behavior for those inputs instead of pretending it is a heap ordering.
    const fallback = finite ? undefined : Array.from(nearest.subarray(0, size)).sort((a, b) => distances[a] - distances[b]);
