    for (let remaining = size; remaining > 0;) {
      const index = fallback ? fallback[size - remaining] : nearest[0];
      remaining--;
      if (!fallback && remaining) {
        nearest[0] = nearest[remaining];
        siftNearest(nearest, distances, 0, remaining);
      }
      yield this.controls[index];
    }
  }

