      const delta = arcResponseStep(jac, residuals, weights.damping);
      if (!delta) continue;
      m.keys.forEach((key, d) => {
        control[key] = (control[key] as number) + m.scale[d] *
          (key === 'support' ? span / m.span : 1) * clamp(delta[d]);
      });
