import {expect, it} from 'vitest';
import {nearestArcExamples} from '../scripts/v0/optimizer/arc_neighbors.ts';
import {arcFeatureDistance} from '../scripts/v0/optimizer/arc_value.ts';
import {makeRng} from '../scripts/lib/rng.ts';

it('matches stable exhaustive retrieval with shared models, local learning, ties and extreme scales', () => {
  const rng = makeRng(72849);
  for (const width of [1, 7, 47, 57, 67]) for (const scale of [1e-200, 1e-50, 1, 1e50, 1e200]) {
    const vector = () => Array.from({length: width}, () => Math.floor(rng() * 8) * scale);
    const model = Array.from({length: 129}, (_, id) => ({id, features: vector()}));
    model[1].features = model[0].features;
    const appended = Array.from({length: 13}, (_, id) => ({id: model.length + id, features: vector()}));
    for (let trial = 0; trial < 8; trial++) {
      const query = trial === 0 ? model[0].features : vector();
      for (const tail of [[], appended]) {
        const expected = [...model, ...tail].map(e => ({e, d: arcFeatureDistance(e.features, query)})).sort((a, b) => a.d - b.d).map(({e}) => e.id);
        const actual = [...nearestArcExamples(model, tail, query)].map(e => e.id);
        expect(actual).toEqual(expected);
        // Partial traversal leaves no mutable query state on the shared index.
        const iterator = nearestArcExamples(model, tail, query);
        expect(iterator.next().value?.id).toBe(expected[0]);
        iterator.return();
        expect([...nearestArcExamples(model, tail, query)].map(e => e.id)).toEqual(expected);
      }
      appended[0].features = vector();
    }
  }
});

it('preserves stable sort semantics for empty, ragged and nonfinite inputs', () => {
  for (const rows of [[], [[]], [[0], [1, 2], [2]], [[0], [NaN], [1]], [[Infinity], [1], [-Infinity]]]) {
    const model = rows.map((features, id) => ({features, id}));
    for (const query of [[], [0], [NaN], [Infinity], [0, 1]]) for (const features of [[1], [NaN], [Infinity], []]) {
      const tail = [{features, id: model.length}];
      const expected = [...model, ...tail].map(e => ({e, d: arcFeatureDistance(e.features, query)})).sort((a, b) => a.d - b.d).map(({e}) => e.id);
      expect([...nearestArcExamples(model, tail, query)].map(e => e.id)).toEqual(expected);
    }
  }
});

