/** Exact, stable nearest-neighbor traversal of immutable model demonstrations.
 * The model owns its tree; each query owns its queue. Compile-local examples
 * stay outside the tree and are merged by their original insertion order. */
import {arcFeatureDistance as distance} from './arc_value.ts';

type Example = {features: readonly number[]};
type Node = {low: number[]; high: number[]; first: number; start: number; end: number; left: number; right: number};
type Entry = {distance: number; order: number; node: number};
const compare = (a: Entry, b: Entry) => a.distance - b.distance || a.order - b.order;

class Queue {
  private entries: Entry[] = [];
  push(entry: Entry): void {
    const a = this.entries;
    let i = a.length;
    a.push(entry);
    while (i > 0) {
      const parent = (i - 1) >>> 1;
      if (compare(a[parent], entry) <= 0) break;
      a[i] = a[parent]; i = parent;
    }
    a[i] = entry;
  }
  pop(): Entry | undefined {
    const a = this.entries, first = a[0], last = a.pop();
    if (!a.length) return first;
    let i = 0;
    for (let child = 1; child < a.length; child = i * 2 + 1) {
      if (child + 1 < a.length && compare(a[child + 1], a[child]) < 0) child++;
      if (compare(last!, a[child]) <= 0) break;
      a[i] = a[child]; i = child;
    }
    a[i] = last!;
    return first;
  }
}

class ModelIndex {
  readonly order: number[];
  readonly nodes: Node[] = [];
  readonly width: number;

  constructor(examples: readonly Example[]) {
    this.width = examples[0]?.features.length ?? 0;
    this.order = examples.map((_, i) => i);
    if (!this.width || examples.some(e => e.features.length !== this.width || e.features.some(v => !Number.isFinite(v)))) return;
    const build = (start: number, end: number): number => {
      const low = Array(this.width).fill(Infinity), high = Array(this.width).fill(-Infinity);
      let first = Infinity;
      for (let i = start; i < end; i++) {
        const index = this.order[i], features = examples[index].features;
        first = Math.min(first, index);
        for (let k = 0; k < this.width; k++) {
          low[k] = Math.min(low[k], features[k]); high[k] = Math.max(high[k], features[k]);
        }
      }
      const node = {low, high, first, start, end, left: -1, right: -1}, index = this.nodes.length;
      this.nodes.push(node);
      if (end - start > 16) {
        let axis = 0;
        for (let k = 1; k < this.width; k++) if (high[k] - low[k] > high[axis] - low[axis]) axis = k;
        const sorted = this.order.slice(start, end).sort((a, b) => examples[a].features[axis] - examples[b].features[axis] || a - b);
        for (let i = 0; i < sorted.length; i++) this.order[start + i] = sorted[i];
        const middle = (start + end) >>> 1;
        node.left = build(start, middle); node.right = build(middle, end);
      }
      return index;
    };
    build(0, examples.length);
  }
}

const indices = new WeakMap<readonly Example[], ModelIndex>();

/** Model arrays and their feature rows must remain immutable. Appended examples
 * are read afresh, so learning within a compile needs no index maintenance. */
export function* nearestArcExamples<T extends Example>(model: readonly T[], appended: readonly T[], query: readonly number[]): IterableIterator<T> {
  let index = indices.get(model);
  if (!index) { index = new ModelIndex(model); indices.set(model, index); }
  const tail = appended.map((e, i) => ({distance: distance(e.features, query), order: model.length + i, node: -1}));
  if (!index.nodes.length || query.length < index.width || query.some(v => !Number.isFinite(v)) || tail.some(e => !Number.isFinite(e.distance))) {
    // NaN subtraction does not define a total order; preserve stable sort's
    // original behavior on nonfinite or ragged input instead of indexing it.
    const ordered = [...model, ...appended].map(e => ({e, distance: distance(e.features, query)})).sort((a, b) => a.distance - b.distance);
    for (const {e} of ordered) yield e;
    return;
  }
  const queue = new Queue(), projection = Array(index.width).fill(0);
  const enqueueNode = (id: number) => {
    const node = index.nodes[id];
    for (let k = 0; k < index.width; k++) projection[k] = Math.max(node.low[k], Math.min(node.high[k], query[k]));
    // Use the exact metric and summation order. Clamping bounds every
    // nonnegative term, including floating-point rounding and overflow.
    queue.push({distance: distance(projection, query), order: node.first, node: id});
  };
  enqueueNode(0);
  for (const entry of tail) queue.push(entry);
  for (let entry = queue.pop(); entry; entry = queue.pop()) {
    if (entry.node < 0) {
      yield entry.order < model.length ? model[entry.order] : appended[entry.order - model.length];
    } else {
      const node = index.nodes[entry.node];
      if (node.left < 0) {
        for (let i = node.start; i < node.end; i++) {
          const order = index.order[i];
          queue.push({distance: distance(model[order].features, query), order, node: -1});
        }
      } else { enqueueNode(node.left); enqueueNode(node.right); }
    }
  }
}

