    let node = 0;
    while (!tree.leaf[node]) node = features[tree.feature[node]] <= tree.threshold[node] ? tree.left[node] : tree.right[node];
    value += tree.value[node];
  }
  return Math.max(0, Math.expm1(value) / 100);
}

