#[derive(Clone)]
struct Slot<V> {
    key: i64,
    value: Option<V>,
}

/// Linear probing with backward-shift deletion. A vacant slot ends a lookup;
/// removal closes its probe chain, so churn needs no tombstones or rehashes.
#[derive(Clone)]
pub(crate) struct FlatIntMap<V> {
    slots: Vec<Slot<V>>,
    len: usize,
}

impl<V> Default for FlatIntMap<V> {
    fn default() -> Self { Self { slots: Vec::new(), len: 0 } }
}

impl<V> FlatIntMap<V> {
    #[inline]
    fn hash(key: i64) -> usize {
        let x = (key as u64).wrapping_mul(0x9E3779B97F4A7C15);
        (x ^ (x >> 32)) as usize
    }

    fn resize(&mut self, capacity: usize) {
        let slots = (0..capacity).map(|_| Slot { key: 0, value: None }).collect();
        let old = std::mem::replace(&mut self.slots, slots);
        self.len = 0;
        for Slot { key, value } in old {
            if let Some(value) = value { self.insert(key, value); }
        }
    }

    /// Existing slot, or the first vacancy on this key's probe chain.
    #[inline]
    fn find_slot(&self, key: i64) -> usize {
        let mask = self.slots.len() - 1;
        let mut index = Self::hash(key) & mask;
        while self.slots[index].value.is_some() && self.slots[index].key != key {
            index = (index + 1) & mask;
        }
        index
    }

    fn insertion_slot(&mut self, key: i64) -> usize {
        if self.slots.is_empty() { self.resize(16); }
        let index = self.find_slot(key);
        // Updating an existing entry never requires spare insertion capacity.
        if self.slots[index].value.is_some() || (self.len + 1) * 10 < self.slots.len() * 7 {
            return index;
        }
        self.resize(self.slots.len() * 2);
        self.find_slot(key)
    }

    #[inline]
    pub(crate) fn get(&self, key: &i64) -> Option<&V> {
        if self.slots.is_empty() { return None; }
        self.slots[self.find_slot(*key)].value.as_ref()
    }

    #[inline]
    pub(crate) fn get_mut(&mut self, key: &i64) -> Option<&mut V> {
        if self.slots.is_empty() { return None; }
        let index = self.find_slot(*key);
        self.slots[index].value.as_mut()
    }

    pub(crate) fn get_or_insert_default(&mut self, key: i64) -> &mut V where V: Default {
        let index = self.insertion_slot(key);
        let slot = &mut self.slots[index];
        if slot.value.is_none() {
            slot.value = Some(V::default());
            slot.key = key;
            self.len += 1;
        }
        slot.value.as_mut().unwrap()
    }

    pub(crate) fn insert(&mut self, key: i64, value: V) -> Option<V> {
        let index = self.insertion_slot(key);
        let slot = &mut self.slots[index];
        let old = slot.value.replace(value);
        slot.key = key;
        if old.is_none() { self.len += 1; }
        old
    }

    pub(crate) fn remove(&mut self, key: &i64) -> Option<V> {
        if self.slots.is_empty() { return None; }
        let mut hole = self.find_slot(*key);
        let value = self.slots[hole].value.take()?;
        self.len -= 1;
        let mask = self.slots.len() - 1;
        let mut next = (hole + 1) & mask;
        while self.slots[next].value.is_some() {
            let home = Self::hash(self.slots[next].key) & mask;
            // Move an entry only if its lookup would pass through this hole.
            if (next.wrapping_sub(home) & mask) >= (next.wrapping_sub(hole) & mask) {
                self.slots[hole].key = self.slots[next].key;
                self.slots[hole].value = self.slots[next].value.take();
                hole = next;
            }
            next = (next + 1) & mask;
        }
        Some(value)
    }
}

