+    this.last = this.prefix.next > 0 ? raw.frames[this.prefix.next - 1] : undefined;
+    const p = this.prefix;
+    this.state = {...p, position: p.position.slice(), velocity: p.velocity.slice(), speed: p.speed.slice(),
+      sledContacts: p.sledContacts.slice(), contactLineIds: p.contactLineIds.slice(), airborne: p.airborne.slice(),
