//! Spatial-grid geometry — bit-faithful port of lr-core's:
//!   - utils/hashNumberPair.js  (`hashIntPair`, Szudzik pair → signed fold)
//!   - grids/getCellsFromLine.js (`classicCells` DDA float walk)
//!   - grids/ClassicGrid.js `getCellsNearEntity` (the 3×3 neighborhood)
//! Pure functions of geometry; no engine state. 14px cells.

use std::collections::HashMap;
use std::hash::{BuildHasher, Hasher};

pub(crate) const GRID_SIZE: f64 = 14.0;

pub(crate) type IntMap<K, V> = HashMap<K, V, IntBuildHasher>;

#[derive(Clone)]
struct Slot<V> {
    key: i64,
    value: Option<V>,
}

/// Linear probing with backward-shift deletion. A vacant slot ends a lookup;
/// removal closes its probe chain, so churn needs no tombstones or rehashes.
#[derive(Clone)]
pub(crate) struct FlatIntMap<V> {
    slots: Vec<Slot<V>>,
    len: usize,
}

impl<V> Default for FlatIntMap<V> {
    fn default() -> Self { Self { slots: Vec::new(), len: 0 } }
}

impl<V> FlatIntMap<V> {
    #[inline]
    fn hash(key: i64) -> usize {
        let x = (key as u64).wrapping_mul(0x9E3779B97F4A7C15);
        (x ^ (x >> 32)) as usize
    }

    fn resize(&mut self, capacity: usize) {
        let slots = (0..capacity).map(|_| Slot { key: 0, value: None }).collect();
        let old = std::mem::replace(&mut self.slots, slots);
        self.len = 0;
        for Slot { key, value } in old {
            if let Some(value) = value { self.insert(key, value); }
        }
    }

    /// Existing slot, or the first vacancy on this key's probe chain.
    #[inline]
    fn find_slot(&self, key: i64) -> usize {
        let mask = self.slots.len() - 1;
        let mut index = Self::hash(key) & mask;
        while self.slots[index].value.is_some() && self.slots[index].key != key {
            index = (index + 1) & mask;
        }
        index
    }

    fn insertion_slot(&mut self, key: i64) -> usize {
        if self.slots.is_empty() { self.resize(16); }
        let index = self.find_slot(key);
        // Updating an existing entry never requires spare insertion capacity.
        if self.slots[index].value.is_some() || (self.len + 1) * 10 < self.slots.len() * 7 {
            return index;
        }
        self.resize(self.slots.len() * 2);
        self.find_slot(key)
    }

    #[inline]
    pub(crate) fn get(&self, key: &i64) -> Option<&V> {
        if self.slots.is_empty() { return None; }
        self.slots[self.find_slot(*key)].value.as_ref()
    }

    #[inline]
    pub(crate) fn get_mut(&mut self, key: &i64) -> Option<&mut V> {
        if self.slots.is_empty() { return None; }
        let index = self.find_slot(*key);
        self.slots[index].value.as_mut()
    }

    pub(crate) fn get_or_insert_default(&mut self, key: i64) -> &mut V where V: Default {
        let index = self.insertion_slot(key);
        let slot = &mut self.slots[index];
        if slot.value.is_none() {
            slot.value = Some(V::default());
            slot.key = key;
            self.len += 1;
        }
        slot.value.as_mut().unwrap()
    }

    pub(crate) fn insert(&mut self, key: i64, value: V) -> Option<V> {
        let index = self.insertion_slot(key);
        let slot = &mut self.slots[index];
        let old = slot.value.replace(value);
        slot.key = key;
        if old.is_none() { self.len += 1; }
        old
    }

    pub(crate) fn remove(&mut self, key: &i64) -> Option<V> {
        if self.slots.is_empty() { return None; }
        let mut hole = self.find_slot(*key);
        let value = self.slots[hole].value.take()?;
        self.len -= 1;
        let mask = self.slots.len() - 1;
        let mut next = (hole + 1) & mask;
        while self.slots[next].value.is_some() {
            let home = Self::hash(self.slots[next].key) & mask;
            // Move an entry only if its lookup would pass through this hole.
            if (next.wrapping_sub(home) & mask) >= (next.wrapping_sub(hole) & mask) {
                self.slots[hole].key = self.slots[next].key;
                self.slots[hole].value = self.slots[next].value.take();
                hole = next;
            }
            next = (next + 1) & mask;
        }
        Some(value)
    }
}

#[derive(Clone, Copy, Default)]
pub(crate) struct IntBuildHasher;

#[derive(Default)]
pub(crate) struct IntHasher {
    state: u64,
}

impl BuildHasher for IntBuildHasher {
    type Hasher = IntHasher;

    #[inline]
    fn build_hasher(&self) -> IntHasher {
        IntHasher { state: 0 }
    }
}

impl Hasher for IntHasher {
    #[inline]
    fn finish(&self) -> u64 {
        // The integer write_* paths fold a key in verbatim (identity). hashbrown
        // (SwissTable) derives the home bucket from the low bits AND a 7-bit control
        // tag from the TOP 7 bits of the hash. The hist/coll/lines_cells keys are
        // small-magnitude Szudzik cell ids / small line ids, so identity leaves the
        // top bits ~all zero — every key collides on the control tag, defeating the
        // SIMD tag filter. Multiply by the golden-ratio odd constant (bijective on
        // u64, so no new key collisions) to spread entropy into both the tag and
        // bucket bits. Probe-order only; never affects key→value mapping or output.
        // (cell_lines uses FlatIntMap, not this hasher.)
        self.state.wrapping_mul(0x9E3779B97F4A7C15)
    }

    #[inline]
    fn write(&mut self, bytes: &[u8]) {
        let mut h = 0xcbf29ce484222325u64;
        for &b in bytes {
            h ^= b as u64;
            h = h.wrapping_mul(0x100000001b3);
        }
        self.state = h;
    }

    #[inline]
    fn write_i32(&mut self, i: i32) {
        self.state = i as u32 as u64;
    }

    #[inline]
    fn write_u32(&mut self, i: u32) {
        self.state = i as u64;
    }

    #[inline]
    fn write_i64(&mut self, i: i64) {
        self.state = i as u64;
    }

    #[inline]
    fn write_u64(&mut self, i: u64) {
        self.state = i;
    }
}

/// hashNumberPair.js: encode each coord (Szudzik), pair, then fold to a signed
/// int. Used verbatim for cell keys; must be exact for negative coords.
#[inline]
pub(crate) fn hash_int_pair(a: i64, b: i64) -> i64 {
    let aa = if a >= 0 { 2 * a } else { -2 * a - 1 };
    let bb = if b >= 0 { 2 * b } else { -2 * b - 1 };
    let c = if aa >= bb {
        aa * aa + aa + bb
    } else {
        bb * bb + aa
    };
    if c & 1 != 0 {
        -(c - 1) / 2 - 1
    } else {
        c / 2
    }
}

// Retained as the inverse of hash_int_pair for the round-trip property test; the hot
// paths now carry cell coords directly (the classic raster walk emits them) so no production
// code unhashes a stored cell any more.
#[allow(dead_code)]
pub(crate) fn unhash_int_pair(n: i64) -> (i64, i64) {
    let c = if n >= 0 { n * 2 } else { -(n + 1) * 2 + 1 };
    let x = (c as f64).sqrt() as i64;
    let r = c - x * x;
    let (aa, bb) = if r < x { (r, x) } else { (x, r - x) };
    let a = if aa & 1 != 0 { -(aa + 1) / 2 } else { aa / 2 };
    let b = if bb & 1 != 0 { -(bb + 1) / 2 } else { bb / 2 };
    (a, b)
}

#[inline]
pub(crate) fn cell_cor_from_scaled(scaled: f64) -> i64 {
    let truncated = scaled as i64;
    if truncated != i64::MIN && scaled < truncated as f64 {
        truncated - 1
    } else {
        truncated
    }
}

#[inline]
pub(crate) fn cell_cor(x: f64) -> i64 {
    cell_cor_from_scaled(x / GRID_SIZE)
}

#[inline]
#[cfg(test)]
pub(crate) fn cell_hash(px: f64, py: f64) -> i64 {
    hash_int_pair(cell_cor(px), cell_cor(py))
}

/// getCellsFromLine.js classicCells — the faithful float walk producing the integer
/// cell coords a line rasterizes into, in walk order. `(p1x,p1y)`→`(p1x+vecx,p1y+vecy)`.
/// Appends `(cx, cy)` pairs (not the Szudzik hash): every consumer immediately needs
/// the coords to enumerate the line's inverse-3×3 neighborhood, and emitting them
/// here avoids an `unhash_int_pair` (a sqrt) per stored cell downstream.
pub(crate) fn append_classic_cells(p1x: f64, p1y: f64, vecx: f64, vecy: f64, cells: &mut Vec<(i64, i64)>) {
    let p2x = p1x + vecx;
    let p2y = p1y + vecy;
    let cs_x = cell_cor(p1x);
    let cs_y = cell_cor(p1y);
    let mut cur_x = cs_x;
    let mut cur_y = cs_y;
    let mut cur_gx = p1x - GRID_SIZE * cs_x as f64;
    let mut cur_gy = p1y - GRID_SIZE * cs_y as f64;
    let ce_x = cell_cor(p2x);
    let ce_y = cell_cor(p2y);

    cells.push((cs_x, cs_y));
    if (vecx == 0.0 && vecy == 0.0) || (cs_x == ce_x && cs_y == ce_y) {
        return;
    }
    let box_left = cs_x.min(ce_x);
    let box_right = cs_x.max(ce_x);
    let box_top = cs_y.min(ce_y);
    let box_bottom = cs_y.max(ce_y);

    let mut posx = p1x;
    let mut posy = p1y;
    loop {
        let dx;
        let dy;
        if cur_x < 0 {
            dx = (GRID_SIZE + cur_gx) * (if vecx > 0.0 { 1.0 } else { -1.0 });
        } else {
            dx = -cur_gx + (if vecx > 0.0 { GRID_SIZE } else { -1.0 });
        }
        if cur_y < 0 {
            dy = (GRID_SIZE + cur_gy) * (if vecy > 0.0 { 1.0 } else { -1.0 });
        } else {
            dy = -cur_gy + (if vecy > 0.0 { GRID_SIZE } else { -1.0 });
        }
        let (nposx, nposy) = if vecx == 0.0 {
            (posx, posy + dy)
        } else if vecy == 0.0 {
            (posx + dx, posy)
        } else {
            let slope = vecy / vecx;
            let y_next = posy + slope * dx;
            if (y_next - posy).abs() < dy.abs() {
                (posx + dx, y_next)
            } else if (y_next - posy).abs() == dy.abs() {
                (posx + dx, posy + dy)
            } else {
                (posx + vecx * dy / vecy, posy + dy)
            }
        };
        let nc_x = cell_cor(nposx);
        let nc_y = cell_cor(nposy);
        if nc_x >= box_left && nc_x <= box_right && nc_y >= box_top && nc_y <= box_bottom {
            cells.push((nc_x, nc_y));
            cur_x = nc_x;
            cur_y = nc_y;
            cur_gx = nposx - GRID_SIZE * nc_x as f64;
            cur_gy = nposy - GRID_SIZE * nc_y as f64;
            posx = nposx;
            posy = nposy;
        } else {
            break;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn flat_map_matches_standard_map_through_wraparound_churn_and_clones() {
        let mut map: FlatIntMap<Vec<i32>> = FlatIntMap::default();
        let mut expected: std::collections::HashMap<i64, Vec<i32>> = std::collections::HashMap::new();
        let mut random = 0x2183_746a_b92c_1e09_u64;
        // Many keys share the final home slot, forcing wrapped probe chains.
        let mut keys: Vec<i64> = (-2000..2000).filter(|&k| FlatIntMap::<()>::hash(k) & 15 == 15).collect();
        keys.extend([i64::MIN, i64::MAX, 0, -1, 1]);
        for step in 0..30_000 {
            random ^= random << 13; random ^= random >> 7; random ^= random << 17;
            let key = keys[(random as usize / 8) % keys.len()];
            match random % 6 {
                0 => assert_eq!(map.insert(key, vec![step]), expected.insert(key, vec![step])),
                1 | 2 => assert_eq!(map.remove(&key), expected.remove(&key)),
                3 => { map.get_or_insert_default(key).push(step); expected.entry(key).or_default().push(step); },
                4 => { if let Some(v) = map.get_mut(&key) { v.push(step); } if let Some(v) = expected.get_mut(&key) { v.push(step); } },
                _ => assert_eq!(map.get(&key), expected.get(&key)),
            }
            assert_eq!(map.len, expected.len());
            if step % 31 == 0 {
                for key in &keys { assert_eq!(map.get(key), expected.get(key)); }
                let mut copy = map.clone();
                for key in &keys { assert_eq!(copy.remove(key).as_ref(), expected.get(key)); }
                assert_eq!(copy.len, 0);
                assert_eq!(map.len, expected.len());
            }
        }
        for key in keys { assert_eq!(map.remove(&key), expected.remove(&key)); }
        assert_eq!(map.len, 0);
    }

    #[test]
    fn hash_int_pair_round_trips_grid_coords() {
        for x in -32..=32 {
            for y in -32..=32 {
                assert_eq!(unhash_int_pair(hash_int_pair(x, y)), (x, y));
            }
        }
    }

    #[test]
    fn branch_floor_cell_coordinate_matches_rust_floor_cast() {
        let edge_values = [
            f64::NEG_INFINITY,
            -1.0e300,
            -28.000000000000004,
            -28.0,
            -27.999999999999996,
            -14.0,
            -0.0,
            0.0,
            13.999999999999998,
            14.0,
            14.000000000000002,
            1.0e300,
            f64::INFINITY,
            f64::NAN,
        ];
        for value in edge_values {
            assert_eq!(cell_cor(value), (value / GRID_SIZE).floor() as i64);
        }

        let mut bits = 0x4d59_5df4_d0f3_3173_u64;
        for _ in 0..100_000 {
            bits = bits
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            let value = f64::from_bits(bits);
            assert_eq!(cell_cor(value), (value / GRID_SIZE).floor() as i64);
        }
    }
}

