import {readFileSync,writeFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {run,instance,workloads} from '/home/holo/line/tools/measure/engine_workload.ts';
const [out,...arms]=process.argv.slice(2),samples=[],artifacts=[];
for(const arm of arms){
 const bytes=readFileSync(`/tmp/engine-under10k-20261103/${arm}.wasm`);artifacts.push({arm,sha256:createHash('sha256').update(bytes).digest('hex')});
 const module=new WebAssembly.Module(bytes);
 for(const workload of workloads){const ex=instance(module),initialWasmBytes=ex.memory.buffer.byteLength;const {frames}=run(ex,workload);samples.push({arm,workload,frames,initialWasmBytes,finalWasmBytes:ex.memory.buffer.byteLength});}
}
writeFileSync(out,JSON.stringify({description:'WASM linear-memory high-water size after complete workload in a fresh instance; not live allocations or RSS.',artifacts,samples},null,2)+'\n');console.log(samples);

