import assert from 'node:assert/strict';
import {copyFileSync,symlinkSync,writeFileSync,readFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import {snapshotSources,sourceOverlay} from '/home/holo/line/tools/measure/engine_sources.ts';
const root='/home/holo/line',study='/tmp/engine-under10k-20261103',out=study+'/memory-milestone',cwd=out+'/worktree';
snapshotSources(study+'/baseline',out+'/reference-source',root);
snapshotSources(study+'/milestone-validation/worktree',cwd,root);
const sources=sourceOverlay(out+'/reference-source',cwd);
symlinkSync(root+'/node_modules',cwd+'/node_modules');
const samples=[],cells=JSON.parse(readFileSync(root+'/tools/parity/cells.json','utf8')).cells;
const binaries=['baseline','milestone'].map(name=>study+'/'+name+'.wasm');
for(const arm of [0,1]){
 const binary=binaries[arm],sha256=createHash('sha256').update(readFileSync(binary)).digest('hex');
 sources.activate(arm);copyFileSync(binary,cwd+'/scripts/lib/native_motion/engine.wasm');
 for(const cell of [61,62]){
  const path=out+'/'+arm+'-'+cell+'.json';
  execFileSync(process.execPath,['--import','tsx','/tmp/engine-dod-20261103/compile_memory.mts',cwd,String(cell),path],{cwd,stdio:'inherit'});
  const track=JSON.parse(readFileSync(path+'.track.json','utf8'));
  assert.equal(track.trackHash,cells[cell].trackHash);assert.equal(track.physicalFrames,cells[cell].physicalFrames);
  samples.push({arm,sourceSha256:sources.sourceSha256[arm],sha256,...JSON.parse(readFileSync(path,'utf8')),trackHash:track.trackHash,physicalFrames:track.physicalFrames});
 }
}
writeFileSync(study+'/milestone-memory-compile.json',JSON.stringify({description:'Frozen full-source arms in the same cwd, fresh process per cell/arm; matching native binary per source arm. WASM linear-memory high-water, not live memory or RSS.',samples},null,2));console.log(samples);

