import pathlib,json
class Reader:
 def __init__(self,b):self.b=b;self.i=0
 def byte(self):v=self.b[self.i];self.i+=1;return v
 def integer(self):
  v=0;s=0
  while True:
   c=self.byte();v|=(c&127)<<s
   if c<128:return v
   s+=7
 def take(self,n):v=self.b[self.i:self.i+n];self.i+=n;return v
 def string(self):return self.take(self.integer()).decode()
def sections(p):
 r=Reader(pathlib.Path(p).read_bytes());r.take(8);out=[]
 while r.i<len(r.b):
  k=r.byte();out.append((k,r.take(r.integer())))
 return out
root='/tmp/engine-under10k-20261103/'
a=sections(root+'named-milestone/wasm32-unknown-unknown/release/lr_engine.wasm');b=sections(root+'milestone.wasm')

names={}
for k,body in a:
 if k!=0:continue
 r=Reader(body)
 if r.string()!='name':continue
 while r.i<len(r.b):
  subsection=r.byte();part=Reader(r.take(r.integer()))
  if subsection==1:
   for _ in range(part.integer()):
    index=part.integer();names[index]=part.string()
pathlib.Path(root+'milestone-wasm-names.json').write_text(json.dumps(names,indent=2)+'\n')
for index in [3,14,15,30,39,40,45,46,49,54,59,62]:print(index,names.get(index))

def bodies(secs):
 r=Reader(next(s for k,s in secs if k==10));return [r.take(r.integer()) for _ in range(r.integer())]
aa=bodies(a);bb=bodies(b)
import difflib
matcher=difflib.SequenceMatcher(None,[len(x) for x in aa],[len(x) for x in bb],autojunk=False)
for op,al,ah,bl,bh in matcher.get_opcodes():
 if op=='equal':
  for x,y in zip(range(al,ah),range(bl,bh)):
   if y in [3,14,15,30,39,40,45,46,49,54,59,62]:print('SIZE-ALIGNED',y,x,len(bb[y]),names.get(x),aa[x]==bb[y])
 else:print('DIFFERING',op,(al,ah),(bl,bh))

