// Diagnostic-only: simulate a conservative velocity-box cache while leaving
// the actual filtering and physics unchanged. Never used for timing evidence.
static mut DIRECTION_COUNTS: [f64; 18] = [0.0; 18];
#[no_mangle]
pub extern "C" fn direction_counts_ptr() -> u32 { &raw const DIRECTION_COUNTS as u32 }
#[derive(Clone, Copy, Default)]
struct DirectionBox { key: i64, epoch: u32, low_x: f64, high_x: f64, low_y: f64, high_y: f64 }
#[inline(never)]
fn count_direction_query(saved: &mut DirectionBox, query: &[*const Line], key: i64, epoch: u32,
    vx: f64, vy: f64, accepted: usize, base: usize) {
    unsafe {
        DIRECTION_COUNTS[base + 0] += 1.0;
        DIRECTION_COUNTS[base + 5] += query.len() as f64;
        if query.is_empty() { DIRECTION_COUNTS[base + 1] += 1.0; return; }
        DIRECTION_COUNTS[base + if accepted == query.len() { 2 } else if accepted == 0 { 3 } else { 4 }] += 1.0;
        if saved.epoch == epoch && saved.key == key && vx >= saved.low_x && vx <= saved.high_x
            && vy >= saved.low_y && vy <= saved.high_y {
            DIRECTION_COUNTS[base + 6] += 1.0; DIRECTION_COUNTS[base + 7] += query.len() as f64; return;
        }
    }
    saved.epoch = 0;
    if !vx.is_finite() || !vy.is_finite() { return; }
    let mut radius = f64::INFINITY;
    for &ptr in query {
        let line = unsafe { &*ptr };
        let direction = line.normx * vx + line.normy * vy;
        if !line.normx.is_finite() || !line.normy.is_finite() || !direction.is_finite() { return; }
        let norm = line.normx.abs() + line.normy.abs();
        if norm > 0.0 { radius = radius.min(0.5 * (direction.abs() / norm)); }
    }
    let bounds = DirectionBox { key, epoch, low_x: vx - radius, high_x: vx + radius,
        low_y: vy - radius, high_y: vy + radius };
    // The radius is only a proposal. Monotone endpoint evaluations of the
    // original floating-point expression must certify every membership.
    for &ptr in query {
        let line = unsafe { &*ptr };
        let (x0, x1) = if line.normx >= 0.0 { (bounds.low_x, bounds.high_x) } else { (bounds.high_x, bounds.low_x) };
        let (y0, y1) = if line.normy >= 0.0 { (bounds.low_y, bounds.high_y) } else { (bounds.high_y, bounds.low_y) };
        let passes = line.normx * vx + line.normy * vy > 0.0;
        let minimum = line.normx * x0 + line.normy * y0;
        let maximum = line.normx * x1 + line.normy * y1;
        if !(if passes { minimum > 0.0 } else { maximum <= 0.0 }) {
            unsafe { DIRECTION_COUNTS[base + 8] += 1.0; } return;
        }
    }
    *saved = bounds;
}
`;
