// Diagnostic-only: predict spatial misses, but run the original collision loop
// and assert that every prediction agrees. No simulated work is skipped.
static mut MISS_COUNTS: [f64; 10] = [0.0; 10];
#[no_mangle]
pub extern "C" fn miss_counts_ptr() -> u32 { &raw const MISS_COUNTS as u32 }
#[derive(Clone, Copy)]
struct MissBox { low_x: f64, high_x: f64, low_y: f64, high_y: f64 }
impl MissBox {
    fn contains(&self, x: f64, y: f64) -> bool {
        x >= self.low_x && x <= self.high_x && y >= self.low_y && y <= self.high_y
    }
    fn excludes(&self, line: &Line) -> bool {
        let (x0, x1) = (self.low_x - line.p1x, self.high_x - line.p1x);
        let (y0, y1) = (self.low_y - line.p1y, self.high_y - line.p1y);
        let (perp_min, perp_max) = crate::history::dot_bounds(line.normx, line.normy, x0, x1, y0, y1);
        if perp_max <= 0.0 || perp_min >= MAX_FORCE_LENGTH { return true; }
        let (along_min, along_max) = crate::history::dot_bounds(line.vecx, line.vecy, x0, x1, y0, y1);
        along_max * line.inv_len_sq < line.left_bound || along_min * line.inv_len_sq > line.right_bound
    }
}
#[inline(never)]
fn certify_miss_box(query: &[*const Line], x: f64, y: f64) -> Option<MissBox> {
    if !x.is_finite() || !y.is_finite() { return None; }
    let exact = MissBox { low_x: x, high_x: x, low_y: y, high_y: y };
    let mut radius = f64::INFINITY;
    for &ptr in query {
        let line = unsafe { &*ptr };
        if ![line.p1x, line.p1y, line.normx, line.normy, line.vecx, line.vecy, line.inv_len_sq]
            .iter().all(|v| v.is_finite()) { return Some(exact); }
        let ox = x - line.p1x; let oy = y - line.p1y;
        let perp = line.normx * ox + line.normy * oy;
        let along = (line.vecx * ox + line.vecy * oy) * line.inv_len_sq;
        let perpendicular_rate = line.normx.abs() + line.normy.abs();
        let along_rate = (line.vecx.abs() + line.vecy.abs()) * line.inv_len_sq;
        let mut margin = 0.0_f64;
        if perp <= 0.0 { margin = margin.max(-perp / perpendicular_rate); }
        if perp >= MAX_FORCE_LENGTH { margin = margin.max((perp - MAX_FORCE_LENGTH) / perpendicular_rate); }
        if along < line.left_bound { margin = margin.max((line.left_bound - along) / along_rate); }
        if along > line.right_bound { margin = margin.max((along - line.right_bound) / along_rate); }
        radius = radius.min(0.5 * margin);
    }
    let proposed = MissBox { low_x: x - radius, high_x: x + radius, low_y: y - radius, high_y: y + radius };
    // Approximate margins only propose the region. Exact monotone endpoint
    // evaluations of the original predicate certify that no point can collide.
    if [proposed.low_x, proposed.high_x, proposed.low_y, proposed.high_y].iter().all(|v| v.is_finite())
        && query.iter().all(|&ptr| proposed.excludes(unsafe { &*ptr })) {
        unsafe { MISS_COUNTS[5] += 1.0; } Some(proposed)
    } else {
        unsafe { MISS_COUNTS[6] += 1.0; } Some(exact)
    }
}
`;
