        let perp = line.normx * ox + line.normy * oy;
        let along = (line.vecx * ox + line.vecy * oy) * line.inv_len_sq;
        let perpendicular_rate = line.normx.abs() + line.normy.abs();
        let along_rate = (line.vecx.abs() + line.vecy.abs()) * line.inv_len_sq;
        let mut margin = 0.0_f64;
        if perp <= 0.0 { margin = margin.max(-perp / perpendicular_rate); }
        if perp >= MAX_FORCE_LENGTH { margin = margin.max((perp - MAX_FORCE_LENGTH) / perpendicular_rate); }
        if along < line.left_bound { margin = margin.max((line.left_bound - along) / along_rate); }
        if along > line.right_bound { margin = margin.max((along - line.right_bound) / along_rate); }
        radius = radius.min(0.5 * margin);
    }
    let proposed = MissBox { low_x: x - radius, high_x: x + radius, low_y: y - radius, high_y: y + radius };
    // Approximate margins only propose the region. Exact monotone endpoint
    // evaluations of the original predicate certify that no point can collide.
    if [proposed.low_x, proposed.high_x, proposed.low_y, proposed.high_y].iter().all(|v| v.is_finite())
        && query.iter().all(|&ptr| proposed.excludes(unsafe { &*ptr })) {
        unsafe { MISS_COUNTS[5] += 1.0; } Some(proposed)
    } else {
        unsafe { MISS_COUNTS[6] += 1.0; } Some(exact)
    }
}
`;
