    /// neighborhood of its raster cells. Adjacent neighborhoods overlap: a
    /// center covered by the preceding cell has already been examined.
    /// Query before truncating; the result is the same running minimum as
    /// truncating after each raster cell, without repeating those lookups.
    pub(crate) fn first_for_added_line(&self, line: &Line) -> Option<i32> {
        let mut best = i32::MAX;
        let mut previous: Option<(i64, i64)> = None;
        for &(gx, gy) in &line.cells {
            for dx in -1..=1 {
                for dy in -1..=1 {
